SELECT r.id AS reservationId, pl.name AS placeName, r.total_price AS totalPrice, r.status AS reservationStatus, r.check_in_at AS checkIn, r.check_out_at AS checkOut FROM reservations r INNER JOIN places pl ON r.place_id = pl.id
pl.host_user_id = #{loginUserId}
AND r.status = #{status}
ORDER BY r.check_in_at DESC;

SELECT availability_id
FROM reservation_slots
WHERE reservation_id = #{reservationId}
